-- European Union milestones (Stage 4 deep-dive/tracker migration)
-- 7 total: 3 deep-dive-only (adoption, entry into force, EN 16931-1:2026 publication)
-- + 4 tracker-matched (eu-transpose, eu-platform-svr-2028, eu-drr, eu-align).
-- The EU has no legacy static HTML page -- this content is authored fresh from
-- the official EC ViDA page and CEN's EN 16931-1:2026 announcement (both verified
-- via live research in July/August 2026), not extracted from an existing static page.
-- None of the tracker's own eu-* DATA entries set anchor:true, so all keep anchor=0,
-- consistent with the Belgium precedent (no anchor default to true here).

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'eu-vida-adopted', id, '2025-03-11', 0, 'https://taxation-customs.ec.europa.eu/taxation/vat/vat-digital-age-vida_en' FROM countries WHERE name_en = 'European Union';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-vida-adopted', 'en', 'ViDA package formally adopted by the Council', 'The Council of the EU gives final approval to the VAT in the Digital Age (ViDA) package -- a Directive, a Regulation, and an Implementing Regulation -- following re-consultation of the European Parliament. The package is rolled out progressively through January 2035.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'eu-vida-force', id, '2025-04-14', 0, 'https://taxation-customs.ec.europa.eu/taxation/vat/vat-digital-age-vida_en' FROM countries WHERE name_en = 'European Union';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-vida-force', 'en', 'ViDA enters into force', 'The ViDA package enters into force. From this date, individual member states may introduce their own mandatory domestic e-invoicing regimes under specific conditions, without a separate EU derogation request -- explaining why several national mandates (e.g. Belgium, Poland) have proceeded on their own schedules well ahead of any EU-wide date.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'eu-transpose', id, '2026-12-31', 0, 'https://taxation-customs.ec.europa.eu/taxation/vat/vat-digital-age-vida_en' FROM countries WHERE name_en = 'European Union';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-transpose', 'en', 'ViDA — Single VAT Registration transposition deadline', 'Member states must transpose the Single VAT Registration (SVR) provisions of the ViDA Directive into national law by this date, so the expanded One Stop Shop (OSS)/Import One Stop Shop (IOSS) scope and related clarifications can apply from 1 January 2027. This deadline is specific to the SVR pillar -- it is separate from, and earlier than, the transposition timelines for ViDA''s platform-economy pillar (2028) and its e-invoicing/Digital Reporting Requirements pillar (2030).', '["If you sell cross-border B2C goods or services within the EU, confirm your OSS/IOSS registration covers the expanded scope taking effect January 2027", "This deadline does not itself require domestic e-invoicing — member states can already introduce their own e-invoicing mandates independently, under derogations available since ViDA''s April 2025 entry into force", "Track your national tax authority''s own transposition and domestic e-invoicing timeline separately from this EU-wide SVR deadline"]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'eu-en16931-2026', id, '2026-03-18', 0, NULL FROM countries WHERE name_en = 'European Union';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-en16931-2026', 'en', 'Revised EN 16931-1:2026 semantic standard published', 'CEN formally publishes the revised EN 16931-1:2026 e-invoicing semantic data model, expanding the original B2G-focused standard to better support complex B2B scenarios ahead of the 2030 Digital Reporting Requirements -- adding fields for IBAN, triangulation indicators, corrective invoice sequencing, and margin schemes.', '["Confirm your invoicing software vendor has a roadmap to support the expanded EN 16931-1:2026 field set"]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'eu-platform-svr-2028', id, '2028-07-01', 0, 'https://taxation-customs.ec.europa.eu/taxation/vat/vat-digital-age-vida_en' FROM countries WHERE name_en = 'European Union';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-platform-svr-2028', 'en', 'ViDA — platform economy & Single VAT Registration go live', 'Digital platforms facilitating short-term accommodation rental and road passenger transport become the deemed supplier for VAT purposes when the underlying provider does not itself charge VAT (e.g. small businesses or individuals). The Single VAT Registration reforms take effect EU-wide, and a mandatory domestic reverse charge applies where a supplier is not established or VAT-registered in the member state of supply.', '["If you operate a qualifying platform (short-term accommodation rental or road passenger transport), confirm your deemed-supplier VAT collection and remittance obligations", "If you supply goods or services in a member state where you are not VAT-registered, confirm whether the new mandatory reverse charge now applies to your transactions", "Review whether the expanded Single VAT Registration model lets you consolidate registrations you currently hold in multiple member states"]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'eu-drr', id, '2030-07-01', 0, 'https://taxation-customs.ec.europa.eu/taxation/vat/vat-digital-age-vida_en' FROM countries WHERE name_en = 'European Union';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-drr', 'en', 'ViDA — cross-border Digital Reporting Requirements', 'Structured e-invoicing and near-real-time Digital Reporting Requirements (DRR) become mandatory EU-wide for cross-border B2B transactions. The EC Sales List is abolished and replaced by DRR.', '["Be able to issue EN 16931-compliant e-invoices within 10 days of the chargeable event for intra-EU B2B sales", "Build near-real-time reporting into your invoicing pipeline ahead of go-live", "Retire EC Sales List (recapitulative statement) processes once DRR replaces them"]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'eu-align', id, '2035-01-01', 0, 'https://taxation-customs.ec.europa.eu/taxation/vat/vat-digital-age-vida_en' FROM countries WHERE name_en = 'European Union';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eu-align', 'en', 'ViDA — domestic system harmonisation', 'All pre-existing domestic e-invoicing and reporting systems (including established clearance models like Italy''s SDI) must be aligned with the harmonised EU ViDA standard.', '["If you operate in a country with its own clearance system, confirm its EN 16931/ViDA alignment plan", "Plan for a single reporting model across all EU markets you operate in"]');
